  perfil: string;
  active: boolean;
  isMaster: boolean;
  subordinados: number[];
  supervisores: number[];
}

// Dados mockados de usuários para permissões
const mockUsersForPermissions: UserWithPermissions[] = [
  {
    id: 1,
    username: "admin",
